actions.script:
const cs = ec.resource.script('component://mr-boss/service/ironstone/customerservice/CustomerService.js')
const facilityIds = cs.servingFacilities(cs.required())
const out = ec.service.sync().name('mantle.product.InventoryReportServices.get#InventoryAtDate').parameters({
    asOfDate, fromDate, productId: productId || null, facilityId: facilityId || null, facilityIds,
    pageIndex, pageSize, historyPageIndex, pageNoLimit}).disableAuthz().call() || {}
// an unknown quantity (history before a facility's first movement) reads Unknown, never blank or zero
const quantityText = (value) => value == null ? ec.l10n.localize('Unknown') : ec.l10n.format(toDecimal(value), '#,##0.###')
const texts = (row) => ({openingText: quantityText(row.openingQuantity), closingText: quantityText(row.closingQuantity)})
ec.context.putAll(out)
totalRows = Array.from(out.totalRows || []).map((row) => Object.assign({}, row, texts(row)))
stockRows = Array.from(out.stockRows || []).map((row) => Object.assign({}, row, texts(row)))
historyRows = Array.from(out.historyRows || []).map((row) => Object.assign({}, row, {balanceText: quantityText(row.balance),
    directionColor: row.quantity < 0 ? 'negative' : row.quantity > 0 ? 'positive' : 'grey'}))
